/** Words for one āyah as [{ tr, en }], or null when not covered. */
export function getJuz30Wbw(surahNumber, ayahNumber) {
  const words = JUZ30_WBW[surahNumber]?.[ayahNumber];
  return words ? words.map(([tr, en]) => ({ tr, en })) : null;
}
